This is a greedy solution with lazy evaluation, for the Hash Code 2017 streaming videos problem.

**Approach.** Aggregate the requests per (endpoint, video) pair. For each (video, cache) pair, the gain from placing the video in the cache depends on which endpoints are connected to that cache and request that video.

Each endpoint-video request has a current best latency `best`, initially LD. Adding video v to cache c gives a gain of sum over endpoints e connected to c of Rn × max(0, best[e][v] − Lc(e,c)). The greedy picks the candidate with the highest gain/size ratio, using a lazy priority queue. The gain only decreases as items are added (submodular), so stale entries can be re-evaluated and pushed back.

**Data structures.**
- Requests are stored per video as a list of (endpoint, count) pairs, merging duplicates with a map.
- For each cache, the connected endpoints are stored as (endpoint, latency) pairs.
- The best latency is stored per request entry. For evaluating (v, c), I iterate over the requests of v and need Lc(e,c). This is looked up through a per-cache array `lat[c][e]` of size C×E = 1e6 ints, which is fine.
- Evaluating gain(v, c) iterates over video v's request entries. The total request entries are at most R = 1e6, so one evaluation costs the number of entries for v. The initial pass over all (v, c) pairs costs C × R = 1e9 in the worst case, which is too heavy. Instead I iterate per request entry (e, v, n), and for each cache c connected to e, add n × (LD − Lc) to `gain[v][c]`. That costs the sum of K over entries, at most 1e6 × 1000 in the worst case, but only for large K. To limit memory, the initial gains go in a hash-free structure: a vector of (v, c) → gain, built per video by a temporary array of size C, then pushed into the heap. A candidate is pushed only if the gain is positive and the size fits.
- Heap entries are (ratio, v, c). On pop, check whether the video already sits in the cache or doesn't fit, then recompute the gain. If the recomputed gain is at least the next top's ratio (or the heap is empty), accept it. Otherwise push it back with the new value.
- On accepting, update best for the video's entries whose endpoint is connected to c, and add the video to the cache.

The ratio is compared as a double, gain/size. The heap may hold up to about 1e7 entries in a bad case (16 bytes each, 160 MB), which fits the memory limit.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int V,E,R,C,X;
    scanf("%d %d %d %d %d",&V,&E,&R,&C,&X);
    vector<int> S(V);
    for(auto&s:S)scanf("%d",&s);
    vector<int> LD(E);
    vector<vector<pair<int,int>>> conn(E);
    vector<int> lat((size_t)C*E,0);
    for(int e=0;e<E;e++){
        int k;
        scanf("%d %d",&LD[e],&k);
        for(int i=0;i<k;i++){
            int c,l;
            scanf("%d %d",&c,&l);
            conn[e].push_back({c,l});
            lat[(size_t)c*E+e]=l;
        }
    }
    vector<map<int,long long>> mp(V);
    for(int i=0;i<R;i++){
        int v,e,n;
        scanf("%d %d %d",&v,&e,&n);
        mp[v][e]+=n;
    }
    struct Ent{int e;long long n;int best;};
    vector<vector<Ent>> ent(V);
    for(int v=0;v<V;v++)
        for(auto&p:mp[v])ent[v].push_back({p.first,p.second,LD[p.first]});
    mp.clear();
    mp.shrink_to_fit();
    typedef tuple<double,int,int> T;
    priority_queue<T> pq;
    vector<long long> g(C,0);
    for(int v=0;v<V;v++){
        if(S[v]>X)continue;
        vector<int> touched;
        for(auto&en:ent[v]){
            for(auto&pc:conn[en.e]){
                if(g[pc.first]==0)touched.push_back(pc.first);
                g[pc.first]+=en.n*(long long)(LD[en.e]-pc.second);
            }
        }
        for(int c:touched){
            if(g[c]>0)pq.push(T((double)g[c]/S[v],v,c));
            g[c]=0;
        }
    }
    vector<int> used(C,0);
    vector<vector<int>> out(C);
    vector<set<int>> has(C);
    while(!pq.empty()){
        auto [r,v,c]=pq.top();
        pq.pop();
        if(used[c]+S[v]>X)continue;
        if(has[c].count(v))continue;
        long long gn=0;
        for(auto&en:ent[v]){
            int l=lat[(size_t)c*E+en.e];
            if(l>0&&l<en.best)gn+=en.n*(long long)(en.best-l);
        }
        if(gn<=0)continue;
        double nr=(double)gn/S[v];
        if(!pq.empty()&&nr<get<0>(pq.top())){
            pq.push(T(nr,v,c));
            continue;
        }
        used[c]+=S[v];
        has[c].insert(v);
        out[c].push_back(v);
        for(auto&en:ent[v]){
            int l=lat[(size_t)c*E+en.e];
            if(l>0&&l<en.best)en.best=l;
        }
    }
    int N=0;
    for(int c=0;c<C;c++)if(!out[c].empty())N++;
    printf("%d\n",N);
    for(int c=0;c<C;c++){
        if(out[c].empty())continue;
        printf("%d",c);
        for(int v:out[c])printf(" %d",v);
        printf("\n");
    }
}
```
